INSERT INTO public.sim_model_versions(id,label,status,engine_id,payload,engine_manifest,source_sha256) SELECT '0.12.0-alpha.collective1.mean1.debt4.remote1.controls1.preview1',label,status,engine_id,jsonb_set(jsonb_set(jsonb_set(payload,'{metadata}','{"id":"vivienda-realism","notes":"Añadida regularización de viviendas consolidadas con oferta formal, aptitud registral y financiación potencial separadas. Acceso y protección: costes por beneficiario, referencias ejecutadas, avales contingentes, parque público y suspensión cancelable. Regularización: máximo conservador 100.000 expedientes; 95 % ya utilizado, solo 5 % de disponibilidad adicional; efectos colectivos reducidos. Fiscalidad: selectores de tipo/recargo, dos componentes ITP/AJD, IRPF/IS, nuevas bases explícitas, recaudación propia y bloqueo transversal del mismo impuesto. Expropiación para alquiler público: justiprecio aproximado, 5 % legal separado, tramitación y rechazo político explícitos. Aplicadas todas las recomendaciones de coherencia: mercado segmentado, stock público, producción privada, beneficiarios, contabilidad financiera, esfuerzo de compra y fiscalidad por hogar. Felicidad social: todos los colectivos salvo no residentes, incidencia fiscal reforzada, PIB real y rebote colectivo finito. Alquiler inicial corregido a la media aritmética AEAT 2024: 9,00 €/m²/mes, territorio fiscal común; mediana SERPAVI sustituida. Sustituida acogida temporal por cupo para nuevas autorizaciones de teletrabajo internacional de rentas altas; controles, costes y canales económicos propios.","title":"Modelo nacional de vivienda","version":"0.12.0-alpha.collective1.mean1.debt4.remote1.controls1.preview1","created_at":"2026-10-04T00:00:00.000Z","updated_at":"2026-10-05T11:58:00.648Z"}'::jsonb),'{model,version}','"0.12.0-alpha.collective1.mean1.debt4.remote1.controls1.preview1"'::jsonb),'{model,release_history}','{"label":"Alfa 0.12","current":"0.12.0-alpha","releases":[{"date":"2026-10-03","label":"Alfa 0.12","changes":["Escenario nacional con demografía dinámica, referencias oficiales y fuentes consultables.","Impuestos y presupuestos ajustables en ambos sentidos, persistentes y con comprobación de financiación.","Informes trimestrales con curvas superpuestas del último año y balance final de partida.","Banco de 120 plantillas de comentarios adaptativos.","Integración en la web, navegación móvil y pie de página común."],"version":"0.12.0-alpha"}],"history_note":"El registro de versiones comienza en Alfa 0.12. Las iteraciones anteriores no disponen de un historial numerado validado.","entries":[{"version":"0.12.0-alpha.collective1.mean1.debt4.remote1.controls1.preview1","date":"2026-10-05","changes":["Previsualización de todas las medidas sobre precios actuales: efecto relativo aislado sin anticipar la evolución general del alquiler y la venta."]},{"version":"0.12.0-alpha.collective1.mean1.debt4.remote1.controls1","date":"2026-10-05","changes":["Integradas las revisiones de deuda pública y sus efectos sociales, el cupo de teletrabajo internacional y los controles de precios de 1–10 años."]},{"version":"0.12.0-alpha.collective1.mean1.remote1.controls1","date":"2026-10-05","title":"Revisión común de controles de precios","changes":["Vigencia 1–10 años, efectos sociales de ambos signos y costes hasta vencimiento.","Precios visibles en euros constantes de 2026, IPC separado y editable.","Retirada de oferta ligada a la restricción efectiva; revisión de comentarios generales."]},{"version":"0.12.0-alpha.collective1.mean1.remote1","date":"2026-10-05","changes":["Sustituida acogida temporal por cupo y umbral de rentas altas para nuevos teletrabajadores internacionales; flujos, demanda, consumo, costes y efectos colectivos propios."]},{"version":"0.12.0-alpha.migration2","date":"2026-10-04","summary":"Migración: presupuesto, expulsiones, retorno con bonus separado, límites acumulados y efectos persistentes; retirada de integración laboral y mediación."},{"version":"0.12.0-alpha.help1","date":"2026-10-04","summary":"Ayudas breves con cifras, reparto de competencias por medida y fuentes oficiales; catálogo cerrado al iniciar."},{"version":"0.12.0-alpha.coherence1","date":"2026-10-04","summary":"Revisión completa de coherencia: esfuerzo de compra, oferta anunciada y mercados segmentados; parque público persistente, capacidad constructiva, inversión privada, reservas de seguros, beneficiarios y perfiles fiscales por hogar. Controles sin efectos heredados, rehabilitación condicionada y programas territoriales sin población ficticia."},{"version":"0.12.0-alpha.collective1","date":"2026-10-05","summary":"Felicidad colectiva ponderada de todos los colectivos nacionales; recortes y presión fiscal con efectos sociales fuertes, PIB real y rebote por sensibilidad de grupo. Indicador en diseño de cada medida."}]}'::jsonb),'{"assets/simulator/housing-policy.js":"5dc84e21a1c3f4dcb44d29075ece481c4a6f96e943b8ea8f93d4f65cb97901b4","assets/simulator/model-config.js":"c4a341d71f194a550864f58a079df5327cdf0a82badba4612bdc14469b69304a","assets/simulator/advanced.js":"6324141a54d360a0a4738a44dd07d95c632fc1cbb0882eb4aac0fa5130f095c7","assets/simulator/national.js":"099037f5602d5dd1e82821ec02c210883713dccdac8664eb7aef6d585b7d81f9","assets/simulator/fiscal.js":"35ae7a021a9fa689917afca743f691961ffb88a84f6f596960341fd45cbd153e","assets/simulator/turn-report.js":"4d4ecec796193c4d5344b543bbf044b033b1bc895cc6da5aae6788db31be0d88","assets/simulator/public-debt.js":"46e376763b0ba24bc42941d987ea326e972712395bb5fd2b57ba64c3f3fbad6c"}'::jsonb,'0a8e31299f039e2f95b38aa20bca7315f13894c24a0312d29da8ae5e428d8223' FROM public.sim_model_versions WHERE id='0.12.0-alpha.collective1.mean1.debt4.remote1.controls1' AND source_sha256='3e90619b61af99c86df113d31191aee974eaba34377e86a01a2c4c2d6f377569';